parameters.text:
=Generate exploratory testing charters for the following Jira user story and its Acceptance Criteria.

User Story / Acceptance Criteria:
{{ $json.chatInput }}

parameters.jsCode:
const result = $input.item.json.output;
const charters = result.charters || [];

let md = `**Overall Focus Summary:** ${result.overallFocusSummary}\n\n`;

for (const c of charters) {
  md += `### [${c.id}] ${c.focusArea} (${c.timeBoxMinutes} min)\n`;
  md += `**Mission:** ${c.mission}\n\n`;
  md += `**Starter Questions:**\n` + c.starterQuestions.map(q => `- ${q}`).join('\n') + `\n\n`;
  md += `**Out of Scope:** ${c.outOfScope}\n\n`;
}

return [{
  json: {
    output: md,
    overallFocusSummary: result.overallFocusSummary,
    charters
  }
}];
